import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { Breakpoint, IconOnlyToggleMode, NavigationSizes } from '../../../../types';
import { AriaAttributes, extractAriaAttributes } from '../../../../utils/a11y-helper';
import { breakpointMapping } from '../../../../utils/breakpoint-mapping';
import { createMenuObserver, handleActiveMenuAttributes } from '../../../../utils/menu-helper';
import { NavigationUtilities } from '../shared/navigation-utilities';

type GlobalSideNavigationItemElement =
  | HTMLGroupuiGlobalSideNavigationItemElement
  | HTMLGroupuiGlobalSideNavigationUtilityItemElement
  | HTMLGroupuiGlobalSideNavigationCategoryElement;

const selectors = [
  'groupui-global-side-navigation-item',
  'groupui-global-side-navigation-utility-item',
  'groupui-global-side-navigation-category',
  'groupui-global-side-navigation-drilldown-item',
];

/**
 * @slot collapse-label - slot for the content of the collapse button
 */

@Component({
  tag: 'groupui-global-side-navigation',
  styleUrl: 'global-side-navigation.scss',
  shadow: true,
})
export class GlobalSideNavigation implements ComponentInterface {
  /**
   * sets the side-navigation size
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  /**
   * activates the dividers
   */
  @Prop({ reflect: true }) readonly divider: boolean;

  /**
   * moves the chevrons to the left side
   */
  @Prop({ reflect: true }) readonly treeLayout: boolean;

  /**
   * Deactivates the active state management.
   */
  @Prop({ reflect: true }) readonly manualMode: boolean = false;

  /**
   * Activates the icon-only view (rail navigation).
   * Caution: Only Navigation items with an icon are displayed.
   * Categories, drill-downs and second-level items are also hidden.
   */
  @Prop({ reflect: true, mutable: true }) iconOnly: boolean;

  /**
   * Expands or collapses the navigation either on click, or on hover
   */
  @Prop({ reflect: true }) readonly iconOnlyToggleMode?: IconOnlyToggleMode;

  /**
   * Custom breakpoint in pixels under which the layout switches to mobile.
   * Overwrites the `breakpoint` property.
   */
  @Prop({ reflect: true }) readonly customBreakpoint: number;

  /**
   * Breakpoint on which the layout switches to mobile.
   */
  @Prop({ reflect: true }) readonly breakpoint: Breakpoint = 'l';

  /**
   * Emitted when the component has loaded.
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * Emitted when the active item changes
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  @Element() host: HTMLElement;

  @State() isMobileLayoutVisible: boolean;

  @State() hovering: boolean = false;

  private ariaAttributes: AriaAttributes;

  private resizeObserver: ResizeObserver;
  private menuObserver: MutationObserver;

  private navigationUtilities = new NavigationUtilities<GlobalSideNavigationItemElement>();

  private delayBeforeCloseOnHover = 160;
  private delayBeforeOpenOnHover = 480;
  private timeout: NodeJS.Timeout;

  @Watch('hovering')
  handleHoverChange(newValue: boolean) {
    clearTimeout(this.timeout);
    this.toggleAfterTimeout(newValue);
  }

  private toggleAfterTimeout(newValue: boolean) {
    this.timeout = setTimeout(
      () => {
        this.iconOnly = !newValue;
      },
      newValue ? this.delayBeforeOpenOnHover : this.delayBeforeCloseOnHover
    );
  }

  @Watch('size')
  updateSizePropOfChild() {
    this.navigationUtilities.setAttribute(
      [...this.navigationUtilities.getAllItems(this.host, selectors.join(', '))],
      'size',
      this.size
    );
  }

  @Watch('divider')
  updateDividerPropOfChild() {
    this.navigationUtilities.updateBooleanAttribute(
      [
        ...this.navigationUtilities.getAllItems(
          this.host,
          'groupui-global-side-navigation-item, groupui-global-side-navigation-utility-item, groupui-global-side-navigation-drilldown-item'
        ),
      ],
      'divider',
      this.divider
    );
  }

  @Watch('treeLayout')
  updateTreeLayoutPropOfChild() {
    this.navigationUtilities.updateBooleanAttribute(this.getAllItemsWithoutPopover(), 'tree-layout', this.treeLayout);
  }

  @Watch('iconOnly')
  updateIconOnlyPropOfChild() {
    this.navigationUtilities.updateBooleanAttribute(
      [...this.navigationUtilities.getAllItems(this.host, selectors.join(', '))],
      'icon-only',
      this.iconOnly
    );

    this.updateBrandLogoIconOnly(this.iconOnly);
  }

  private updateBrandLogoIconOnly(isIconOnly: boolean) {
    const logo = this.host.querySelector('groupui-brand-logo');
    if (!logo) return;

    if (isIconOnly) {
      logo.setAttribute('icon-only', '');
    } else {
      logo.removeAttribute('icon-only');
    }
  }

  componentWillLoad(): void {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.updateSizePropOfChild();
    this.updateDividerPropOfChild();
    this.updateTreeLayoutPropOfChild();
    this.updateIconOnlyPropOfChild();
    this.updateBrandLogo();
    this.updateBurgerMenu();
    this.addResizeObserver();
    this.checkForActiveChildItems();
    this.addMenuStyling();
    this.menuObserver = createMenuObserver();
  }

  disconnectedCallback() {
    this.resizeObserver?.disconnect();
    this.menuObserver?.disconnect();
  }

  @Listen('click')
  handleClick(event: Event): void {
    const item =
      (event.target as HTMLElement).closest('groupui-global-side-navigation-item') ||
      (event.target as HTMLElement).closest('groupui-global-side-navigation-utility-item');

    if (!item || item.disabled) {
      return;
    }

    if (this.isInsideMenu(item)) {
      return;
    }

    if (!this.manualMode) {
      if (this.navigationUtilities.isLeafItem(item, 'groupui-global-side-navigation-item') || this.iconOnly) {
        this.navigationUtilities.removeActiveFromAllItems(
          this.host,
          'groupui-global-side-navigation-item, groupui-global-side-navigation-utility-item'
        );
        this.navigationUtilities.setActiveItem(item);
        this.groupuiChange.emit();
        this.host.dispatchEvent(new globalThis.Event('change'));
        return;
      }

      if (this.navigationUtilities.hasActiveChildItems(item, 'groupui-global-side-navigation-item')) {
        item.hasAttribute('open')
          ? this.navigationUtilities.setActiveItem(item)
          : this.navigationUtilities.removeActiveItem(item);
      }
    }

    this.navigationUtilities.toggleOpenState(item);
  }

  private isInsideMenu(item: Element) {
    return item.closest('groupui-menu') !== null;
  }

  componentDidLoad() {
    handleActiveMenuAttributes(this.host, this.menuObserver);
    this.groupuiDidLoad.emit();
  }

  private checkForActiveChildItems() {
    this.navigationUtilities.getAllItems(this.host, selectors.join(', ')).forEach((item) => {
      if (this.navigationUtilities.hasActiveChildItems(item, 'groupui-global-side-navigation-item')) {
        item.hasAttribute('open')
          ? this.navigationUtilities.removeActiveItem(item)
          : this.navigationUtilities.setActiveItem(item);
      }
    });
  }

  private updateBrandLogo() {
    const logo = this.host.querySelector('groupui-brand-logo');
    if (!logo) {
      return;
    }
    if (!this.isMobileLayoutVisible) {
      logo.alwaysCompact = true;
    }
    logo.setAttribute('slot', 'logo');
  }

  private updateBurgerMenu() {
    const burger = this.host.querySelector('groupui-burger-menu');
    if (burger) {
      burger.classList.add('in-side-navigation');
      burger.setAttribute('slot', 'burger');
    }
  }

  private addResizeObserver() {
    this.resizeObserver = new ResizeObserver((element) => {
      const breakpoint = this.customBreakpoint ?? breakpointMapping.get(this.breakpoint);
      this.isMobileLayoutVisible = element[0].contentRect.width < breakpoint;
      this.updateBrandLogo();
    });

    this.resizeObserver?.observe(window.document.documentElement);
  }

  private getAllItemsWithoutPopover(): GlobalSideNavigationItemElement[] {
    return this.navigationUtilities
      .getAllItems(this.host, 'groupui-global-side-navigation-item, groupui-global-side-navigation-utility-item')
      .filter((utilityItem) => {
        const hasPopoverContent = utilityItem.querySelector('[slot="popover"]');
        return !hasPopoverContent;
      });
  }

  private toggle = () => {
    this.iconOnly = !this.iconOnly;
  };

  private getExpandButton() {
    if (this.iconOnlyToggleMode !== 'on-click') return;

    return (
      <button id="expand" type="button" onClick={this.toggle}>
        <div>
          {!this.iconOnly && <slot name="collapse-label"></slot>}
          <groupui-icon
            aria-hidden="true"
            name={this.iconOnly ? 'chevron-double-right-24' : 'chevron-double-left-24'}
          ></groupui-icon>
        </div>
      </button>
    );
  }

  private addMenuStyling() {
    this.host.querySelectorAll('groupui-menu').forEach((menu) => {
      menu.setAttribute('placement', 'right-start');
      menu.setAttribute('display', 'block');
    });
  }

  private addExpandOnHoverListener() {
    return this.iconOnlyToggleMode === 'on-hover'
      ? {
          onMouseEnter: () => {
            this.hovering = true;
          },
          onMouseLeave: () => {
            this.hovering = false;
          },
        }
      : {};
  }

  render() {
    return (
      <Host {...this.addExpandOnHoverListener()}>
        <nav {...this.ariaAttributes} class={this.isMobileLayoutVisible ? 'mobile' : ''}>
          <slot name="logo"></slot>
          {!this.isMobileLayoutVisible && <slot name="nav-items"></slot>}
          {!this.isMobileLayoutVisible && <slot name="utilities"></slot>}
          {this.isMobileLayoutVisible && <slot name="burger"></slot>}
          {this.getExpandButton()}
        </nav>
      </Host>
    );
  }
}
